INSERT INTO package_questions (package_id, question_json, hash_logico, order_index, status) VALUES ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A parede torácica é composta por costelas, cartilagens e músculos. Como é denominada a região do espaço intercostal onde se deve realizar a toracocentese para evitar lesão do feixe vasculonervoso intercostal?","options":{"a":"Borda superior da costela inferior.","b":"Borda inferior da costela superior.","c":"Centro do espaço intercostal.","d":"Posteriormente à linha axilar média.","e":"Anteriormente à linha paraesternal."},"answer":"a","rationale":"O feixe vasculonervoso intercostal (Veia, Artéria, Nervo) localiza-se no sulco da costela, na sua borda inferior. Portanto, procedimentos de drenagem ou punção devem ser feitos rente à borda superior da costela de baixo.","option_rationales":{"a":"Correta. Local seguro para evitar o feixe VAN.","b":"Errada. Risco alto de lesar a artéria e o nervo intercostais.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Tórax","Topografia"]}', '3300aa97a91fd6c3d8e52777c7b8ada3', 150, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O coração é dividido em quatro câmaras. Qual estrutura anatômica separa o átrio direito do ventrículo direito e impede o refluxo de sangue durante a sístole ventricular?","options":{"a":"Válvula mitral.","b":"Válvula tricúspide.","c":"Válvula aórtica.","d":"Válvula pulmonar.","e":"Septo primum."},"answer":"b","rationale":"A valva atrioventricular direita é a tricúspide. A mitral (bicúspide) localiza-se no lado esquerdo.","option_rationales":{"a":"Errada. Lado esquerdo.","b":"Correta. Valva do coração direito.","c":"Errada. Semilunar de saída esquerda.","d":"Errada. Semilunar de saída direita.","e":"Errada. Estrutura fetal do septo interatrial."},"difficulty":"Fácil","tags":["Anatomia","Tórax","Cardiologia"]}', '014bf36e4c64f779e94c12babadcf612', 151, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A circulação coronariana é vital para o miocárdio. Qual artéria é geralmente responsável por suprir o nó sinoatrial (marcapasso natural) na maioria da população?","options":{"a":"Artéria coronária esquerda.","b":"Artéria coronária direita.","c":"Artéria descendente anterior.","d":"Artéria circunflexa.","e":"Artéria marginal esquerda."},"answer":"b","rationale":"Em cerca de 60% das pessoas, a artéria do nó sinoatrial origina-se da artéria coronária direita.","option_rationales":{"a":"Errada.","b":"Correta. Fonte principal para o sistema de condução inicial.","c":"Errada. Supre o septo e parede anterior.","d":"Errada. Supre a parede lateral esquerda.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Tórax","Vascularização"]}', '983c9e6ca8a1c93ab0590411ae582c3d', 152, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O mediastino é o compartimento central da cavidade torácica. Qual estrutura marca o limite entre o mediastino superior e o mediastino inferior?","options":{"a":"Abertura superior do tórax.","b":"Plano transverso do tórax (nível do ângulo de Louis).","c":"Diafragma.","d":"Pericárdio anterior.","e":"Bifurcação da traqueia."},"answer":"b","rationale":"O plano imaginário que passa pelo ângulo esternal (de Louis) e pelo disco intervertebral entre T4 e T5 divide o mediastino em superior e inferior.","option_rationales":{"a":"Errada. Limite superior absoluto.","b":"Correta. Marco anatômico fundamental para divisão mediastinal.","c":"Errada. Limite inferior absoluto.","d":"Errada.","e":"Errada. Ocorre no nível do plano, mas não é a definição do limite."},"difficulty":"Média","tags":["Anatomia","Tórax","Topografia"]}', '0ad869a4b64ecf795e3c62c96befd8c5', 153, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Os pulmões possuem lobos separados por fissuras. Quantos lobos possui o pulmão ESQUERDO e qual a sua principal fissura?","options":{"a":"Três lobos; fissuras oblíqua e horizontal.","b":"Dois lobos; fissura oblíqua.","c":"Três lobos; fissura oblíqua.","d":"Dois lobos; fissuras oblíqua e horizontal.","e":"Um lobo contínuo."},"answer":"b","rationale":"O pulmão esquerdo é dividido em lobos superior e inferior pela fissura oblíqua. O pulmão direito tem três lobos e duas fissuras.","option_rationales":{"a":"Errada. Descrição do pulmão direito.","b":"Correta. Anatomia pulmonar esquerda padrão.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Tórax","Pneumologia"]}', '7f7cd86fc4fd587af02e358bd375aec4', 154, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O sistema de condução do coração coordena o ciclo cardíaco. Após o estímulo deixar o Nó Atrioventricular (AV), por qual estrutura ele passa ANTES de se dividir nos ramos direito e esquerdo para os ventrículos?","options":{"a":"Fibras de Purkinje.","b":"Nó sinoatrial.","c":"Fascículo atrioventricular (Feixe de His).","d":"Músculos papilares.","e":"Banda moderadora."},"answer":"c","rationale":"A sequência correta é: Nó SA -> Vias Internodais -> Nó AV -> Feixe de His -> Ramos Direito/Esquerdo -> Fibras de Purkinje.","option_rationales":{"a":"Errada. Terminal do sistema.","b":"Errada. Início do sistema.","c":"Correta. Conexão eletrofisiológica entre átrios e ventrículos.","d":"Errada. Estruturas mecânicas.","e":"Errada. Contém parte do ramo direito."},"difficulty":"Média","tags":["Anatomia","Tórax","Fisiologia/Cardiologia"]}', 'a260853ae3729e0e857bbb91e903c651', 155, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A aorta torácica emite diversos ramos. Qual dos seguintes vasos é o PRIMEIRO ramo do arco da aorta (da direita para a esquerda)?","options":{"a":"Artéria carótida comum esquerda.","b":"Artéria subclávia esquerda.","c":"Tronco braquiocefálico.","d":"Artéria coronária direita.","e":"Artéria carótida comum direita."},"answer":"c","rationale":"Os três ramos clássicos do arco da aorta são: 1. Tronco braquiocefálico; 2. Carótida comum esquerda; 3. Subclávia esquerda.","option_rationales":{"a":"Errada. Segundo ramo.","b":"Errada. Terceiro ramo.","c":"Correta. Origina as artérias subclávia e carótida comuns direitas.","d":"Errada. Ramo da aorta ascendente.","e":"Errada. Ramo do tronco braquiocefálico."},"difficulty":"Fácil","tags":["Anatomia","Tórax","Angiologia"]}', '459e9bb211d748d0b07397effe326ef6', 156, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"No hilo pulmonar, as estruturas entram e saem dos pulmões. Qual a posição relativa habitual da ARTÉRIA PULMONAR em relação ao brônquio principal no hilo do pulmão ESQUERDO?","options":{"a":"Anterior ao brônquio.","b":"Posterior ao brônquio.","c":"Superior ao brônquio.","d":"Inferior ao brônquio.","e":"Medial ao brônquio."},"answer":"c","rationale":"Mnemônico ''S'' para Superior no pulmão esquerdo (Left) e ''A'' para Anterior no direito (Right). No lado esquerdo, a artéria pulmonar é mais superior.","option_rationales":{"a":"Errada.","b":"Errada.","c":"Correta. Relação topográfica específica do hilo esquerdo.","d":"Errada.","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Tórax","Pneumologia"]}', 'b35ec243d1b4741d0b0bd9b4e444784a', 157, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O diafragma é o principal músculo respiratório. Por qual dessas aberturas (hiatos) do diafragma passa o ducto torácico junto com a maior artéria do corpo?","options":{"a":"Hiato esofágico.","b":"Hiato aórtico.","c":"Forame da veia cava.","d":"Trígono esternocostal.","e":"Hiato de Bochdalek."},"answer":"b","rationale":"O hiato aórtico (nível T12) permite a passagem da aorta descendente, do ducto torácico e da veia ázigo.","option_rationales":{"a":"Errada. Passam esôfago e troncos vagais (T10).","b":"Correta. Nível mais inferior e posterior de trânsito diafragmático.","c":"Errada. Passa a veia cava inferior (T8).","d":"Errada.","e":"Errada. Defeito congênito."},"difficulty":"Média","tags":["Anatomia","Tórax","Splatcnologia"]}', '60c9d23ab81b9d4ac296be08125585e4', 158, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O esôfago atravessa o tórax no mediastino posterior. Qual estrutura nervosa forma um plexo ao redor do esôfago e o acompanha através do hiato diafragmático?","options":{"a":"Nervo frênico.","b":"Nervos intercostais.","c":"Nervos vagos (X par).","d":"Cadeia simpática torácica.","e":"Nervos esplâncnicos maiores."},"answer":"c","rationale":"Os nervos vagos direito e esquerdo formam os troncos vagais anterior e posterior sobre a superfície do esôfago abdominal/torácico distal.","option_rationales":{"a":"Errada. Passam lateralmente ao pericárdio.","b":"Errada.","c":"Correta. Relação longitudinal clássica no mediastino posterior.","d":"Errada. Situam-se nas articulações costovertebrais.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Tórax","Neuroanatomia"]}', '28c5fdb41961e14ef1bb63cb1c26f8ad', 159, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"As faces do coração são descritas de acordo com as estruturas adjacentes. Qual câmara cardíaca forma a maior parte da FACE DIAFRAGMÁTICA (inferior) do coração?","options":{"a":"Átrio direito.","b":"Ventrículo direito.","c":"Átrio esquerdo.","d":"Ventrículo esquerdo.","e":"Aurícula esquerda."},"answer":"d","rationale":"A face diafragmática é formada principalmente pelo ventrículo esquerdo e, em menor parte, pelo ventrículo direito.","option_rationales":{"a":"Errada. Forma a face lateral direita.","b":"Errada. Forma a maior parte da face esternocostal (anterior).","c":"Errada. Forma a base (posterior).","d":"Correta. Parte muscular mais espessa voltada para o diafragma.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Tórax","Cardiologia"]}', '467a64dddc4967e0b12b94ca6d3522df', 160, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A drenagem linfática do tórax é realizada em grande parte pelo ducto torácico. Onde este ducto normalmente desemboca no sistema venoso?","options":{"a":"Veia cava superior.","b":"Átrio direito diretamente.","c":"Junção da veia jugular interna esquerda com a veia subclávia esquerda (ângulo venoso de Pirogoff).","d":"Veia ázigo.","e":"Veia braquiocefálica direita."},"answer":"c","rationale":"O ducto torácico drena 3/4 da linfa do corpo e desemboca no ângulo venoso esquerdo. O lado direito superior é drenado pelo ducto linfático direito.","option_rationales":{"a":"Errada.","b":"Errada.","c":"Correta. Ponto crítico de retorno da linfa para o sangue.","d":"Errada.","e":"Errada. Local de desembocadura do ducto linfático direito."},"difficulty":"Média","tags":["Anatomia","Tórax","Imunologia/Angiologia"]}', 'cfc1bce8f94f9b165a6cff9b7369f1f4', 161, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"As pleuras são membranas serosas que envolvem os pulmões. Qual o nome do espaço de reserva pleural situado inferiormente, onde o pulmão não entra durante a expiração tranquila e onde o fluido costuma se acumular em derrames pleurais?","options":{"a":"Cúpula pleural.","b":"Recesso costodiafragmático.","c":"Recesso costomediastinal.","d":"Cavidade pericárdica.","e":"Ligamento pulmonar."},"answer":"b","rationale":"Os recessos costodiafragmáticos são as porções mais profundas da cavidade pleural, localizados na reflexão da pleura costal para a diafragmática.","option_rationales":{"a":"Errada. Parte superior sobre o ápice pulmonar.","b":"Correta. Local clínico de detecção de derrames em radiografias.","c":"Errada. Localizado anteriormente próximo ao esterno.","d":"Errada. Membrana do coração.","e":"Errada. Dobra de pleura abaixo do hilo."},"difficulty":"Fácil","tags":["Anatomia","Tórax","Pneumologia"]}', '3e78cecad8b55a15ed1e25e7c93c21df', 162, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A artéria torácica interna (mamária interna) é um ramo da artéria subclávia. Quais são seus dois ramos terminais emitidos ao nível do 6º espaço intercostal?","options":{"a":"Artéria epigástrica superior e artéria musculofrênica.","b":"Artéria pericardiocrênica e artéria frênica superior.","c":"Artéria intercostal anterior e artéria timica.","d":"Artéria torácica lateral e artéria subescapular.","e":"Artéria bronquial e artéria esofágica."},"answer":"a","rationale":"A artéria torácica interna desce lateralmente ao esterno e divide-se em musculofrênica (que segue o rebordo costal) e epigástrica superior (que entra na bainha do reto abdominal).","option_rationales":{"a":"Correta. Divisão terminal padrão.","b":"Errada. Ramos colaterais.","c":"Errada. Ramos colaterais segmentares coincidem com os espaços intercostais.","d":"Errada. Ramos da artéria axilar.","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Tórax","Angiologia"]}', 'b1d5390f08bd10cdecdc613703f08a2c', 163, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O pericárdio é um saco fibrosseroso. Qual nervo fornece a inervação SENSITIVA para o pericárdio parietal e pleura mediastinal, podendo causar dor referida no ombro em casos de irritação?","options":{"a":"Nervo vago.","b":"Nervo frênico.","c":"Nervos intercostais.","d":"Nervo laríngeo recorrente.","e":"Cadeia simpática."},"answer":"b","rationale":"O nervo frênico (C3-C5) supre o diafragma e também carrega fibras sensitivas do pericárdio e pleura central. Como compartilha raízes com os nervos do ombro, a dor pode ser referida lá.","option_rationales":{"a":"Errada.","b":"Correta. Explica o surgimento de dor epigástrica ou escapular em pericardites.","c":"Errada. Inervam a pleura costal periférica.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Tórax","Neuroanatomia"]}', 'c9b6d468c29ccb029106c977cc0a624f', 164, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A traqueia divide-se na carina para formar os brônquios principais. Qual a principal diferença anatômica entre o brônquio principal DIREITO e o ESQUERDO, explicada pela frequência de aspiração de corpos estranhos?","options":{"a":"O direito é mais longo e estreito.","b":"O direito é mais largo, curto e verticalizado.","c":"O esquerdo é mais calibroso e vertical.","d":"O esquerdo passa acima do arco da aorta.","e":"Não há diferença anatômica significativa."},"answer":"b","rationale":"O brônquio principal direito é mais calibroso, curto e segue uma trajetória mais vertical que o esquerdo, facilitando a entrada de objetos aspirados.","option_rationales":{"a":"Errada.","b":"Correta. Base anatômica para a patologia de aspiração.","c":"Errada.","d":"Errada. Passa abaixo do arco da aorta.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Tórax","Pneumologia"]}', '0bd7341fc6ade170d707cb2a25fa051b', 165, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A veia ázigo é um importante canal colateral entre as veias cavas. Onde ela desemboca?","options":{"a":"Veia cava inferior.","b":"Átrio direito.","c":"Veia cava superior.","d":"Veia braquiocefálica esquerda.","e":"Veia porta."},"answer":"c","rationale":"A veia ázigo sobe pelo lado direito do mediastino posterior e ''encavalga'' o brônquio principal direito para desembocar na face posterior da veia cava superior.","option_rationales":{"a":"Errada.","b":"Errada.","c":"Correta. Ponto de convergência da drenagem venosa da parede torácica.","d":"Errada. Local de desembocadura da veia hemiázigo superior (acessória).","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Tórax","Angiologia"]}', '7969c8e76b18043b5ff3148c93fcd9ce', 166, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"As válvulas cardíacas semilunares impedem o refluxo de sangue dos grandes vasos para os ventrículos. Onde se localizam os óstios das ARTÉRIAS CORONÁRIAS?","options":{"a":"No ventrículo esquerdo, abaixo da válvula aórtica.","b":"Nos seios da aorta (seios de Valsalva), logo acima da válvula aórtica.","c":"Na aorta ascendente, 5 cm acima da válvula.","d":"No arco da aorta.","e":"Nos seios pulmonares."},"answer":"b","rationale":"As coronárias direita e esquerda originam-se dos seios aórticos direito e esquerdo, respectivamente. O seio posterior é não coronariano.","option_rationales":{"a":"Errada. Origem é arterial, não ventricular.","b":"Correta. Vascularização cardíaca inicia-se na base da aorta.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Tórax","Vascularização"]}', 'd6e114acb246c8cf9b91dbe4391d243f', 167, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ligamento arterioso é um remanescente fibroso de uma estrutura fetal importante. Qual era essa estrutura e quais vasos ela conectava?","options":{"a":"Forame oval; entre os átrios.","b":"Ducto venoso; entre veia umbilical e veia cava.","c":"Ducto arterioso; entre artéria pulmonar e arco da aorta.","d":"Artéria umbilical; entre ilíaca e placenta.","e":"Uraco; entre bexiga e umbigo."},"answer":"c","rationale":"O ducto arterioso permite que o sangue pule os pulmões fetais não funcionantes. Após o nascimento, ele se oblitera e torna-se o ligamento arterioso.","option_rationales":{"a":"Errada. Torna-se a fossa oval.","b":"Errada. Torna-se o ligamento venoso.","c":"Correta. Evolução da circulação fetal para a adulta.","d":"Errada. Tornam-se ligamentos umbilicais mediais.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Tórax","Embriologia/Cardiologia"]}', '6fd395d53ad391b909b94bf1b96014b3', 168, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O mediastino posterior contém diversas estruturas. Qual dessas estruturas localiza-se mais à DIREITA, cruzando anteriormente as artérias intercostais posteriores?","options":{"a":"Ducto torácico.","b":"Esôfago.","c":"Veia ázigo.","d":"Aorta descendente.","e":"Veia hemiázigo."},"answer":"c","rationale":"A veia ázigo é a estrutura mais lateral direita do mediastino posterior. A aorta é lateral esquerda.","option_rationales":{"a":"Errada. Central, entre aorta e ázigo.","b":"Errada. Central.","c":"Correta. Relação anatômica de lateralidade no tórax.","d":"Errada. Lateral esquerda.","e":"Errada. Lateral esquerda."},"difficulty":"Difícil","tags":["Anatomia","Tórax","Topografia"]}', '7e5dc3c8d2e2f90e1383c97a43bfa81b', 169, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Músculos papilares e cordas tendíneas são essenciais para a função valvar atrioventricular. Qual a função exata dessas estruturas durante a sístole ventricular?","options":{"a":"Puxar as válvulas para baixo para abrir a passagem de sangue.","b":"Contrair para ejetar sangue para as artérias.","c":"Impedir o prolapso (eversão) das cúspides valvares para dentro dos átrios.","d":"Bombear oxigênio para o miocárdio.","e":"Fechar as válvulas semilunares."},"answer":"c","rationale":"Os músculos papilares não fecham a valva (quem faz isso é a pressão do sangue), eles apenas seguram as cordas tendíneas para que as cúspides não virem ''do avesso'' para dentro dos átrios sob alta pressão.","option_rationales":{"a":"Errada. Isso seria na diástole, mas a abertura é passiva.","b":"Errada. Função do ventrículo como um todo.","c":"Correta. Mecanismo de contenção mecânica das valvas AV.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Tórax","Cardiologia"]}', '0f5f6b2b34e0aba81faae19be1320b62', 170, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A glândula timo localiza-se no mediastino e é importante para a maturação de linfócitos T. Em qual compartimento do mediastino inferior ela pode ser encontrada, além de sua localização no mediastino superior?","options":{"a":"Mediastino anterior.","b":"Mediastino médio.","c":"Mediastino posterior.","d":"Apenas no mediastino superior.","e":"Atrás do esôfago."},"answer":"a","rationale":"O timo localiza-se no mediastino superior e estende-se para o mediastino anterior (entre o pericárdio e o esterno).","option_rationales":{"a":"Correta. Compartimento que contém timo (resquícios no adulto) e linfonodos.","b":"Errada. Contém o coração.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Tórax","Imunologia"]}', '94a164de50e7b0c88aa9c1c77fa55b1e', 171, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O mamilo é um marco de superfície útil para a anatomia do tórax masculino. Em qual espaço intercostal ele se localiza habitualmente?","options":{"a":"2º espaço intercostal.","b":"3º espaço intercostal.","c":"4º espaço intercostal.","d":"5º espaço intercostal.","e":"6º espaço intercostal."},"answer":"c","rationale":"No homem, o mamilo localiza-se geralmente lateralmente à linha medioclavicular no 4º espaço intercostal.","option_rationales":{"a":"Errada.","b":"Errada.","c":"Correta. Marco clássico para ausculta e procedimentos.","d":"Errada. Frequentemente local do ápice cardíaco (ictus cordis).","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Tórax","Superfície"]}', 'fba715bf10b487c647360133e9016a12', 172, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A membrana suprapleural (fáscia de Sibson) é um espessamento da fáscia endotorácica. Qual a sua função e localização?","options":{"a":"Cobre o ápice do pulmão no nível da abertura superior do tórax.","b":"Cobre o diafragma inferiormente.","c":"Ancoragem do pericárdio ao esterno.","d":"Separa os pulmões um do outro no plano sagital.","e":"Forma o ligamento pulmonar inferior."},"answer":"a","rationale":"A fáscia de Sibson reforça a cúpula pleural e impede que o pulmão e a pleura protruam para o pescoço durante a respiração.","option_rationales":{"a":"Correta. Proteção superior da cavidade torácica.","b":"Errada.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Tórax","Topografia"]}', '1fa3050fae1cb11c1df2a1f4ad95c376', 173, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Qual estrutura nervosa cruza ANTERIORMENTE a raiz do pulmão no seu trajeto para o diafragma, acompanhada pelos vasos pericardiocrênicos?","options":{"a":"Nervo vago.","b":"Nervo frênico.","c":"Nervo laríngeo recorrente.","d":"Tronco simpático.","e":"Nervo esplâncnico maior."},"answer":"b","rationale":"O nervo frênico passa anteriormente ao hilo pulmonar, enquanto o nervo vago passa posteriormente ao hilo.","option_rationales":{"a":"Errada. Passa posterior ao hilo.","b":"Correta. Relação topográfica fundamental no tórax.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Tórax","Neuroanatomia"]}', 'ef031f9c1899a64ab40056f85c895f5f', 174, 'draft');